===================================================================
--- index.html
+++ index.html
@@ -26,4 +26,30 @@
     <main id="main"></main>
     <footer class="footer">A little more curious, a little more connected. &nbsp;·&nbsp; Made for thoughtful explorers.</footer>
   </div>
   <script>
+    const places = [
+      {name:'Oaxaca, Mexico',short:'Oaxaca',emoji:'🌞',tag:'MOUNTAIN TOWN · MEXICO',palette:['#f4d293','#6b9b81','#c76843','#e9b46b'],clues:['Zapotec and Mixtec are among the Indigenous languages spoken here, alongside Spanish.','Oaxaca City sits in a valley framed by the Sierra Madre del Sur.','The region is known for many distinct moles—not just one recipe.'],fact:'Oaxaca is home to many Indigenous communities and languages. Its foodways and traditions vary from town to town.',contrast:'Compare: Yucatán is a low-lying peninsula with a strong Maya-language presence; Oaxaca is a mountainous, highly multilingual region.'},
+      {name:'Kerala, India',short:'Kerala',emoji:'🌴',tag:'BACKWATER COUNTRY · INDIA',palette:['#e8c879','#5b9e84','#337f70','#f0a477'],clues:['Malayalam is the state’s main official language.','A network of lagoons and canals is known as the backwaters.','Onam is celebrated by many communities; pookalam flower designs are one festive tradition.'],fact:'Kerala has Hindu, Muslim, Christian, Jewish and other communities, with lively regional and local differences.',contrast:'Compare: Goa lies farther north on India’s west coast, with Konkani among its major languages; Kerala’s main language is Malayalam.'},
+      {name:'Jeju Island, South Korea',short:'Jeju Island',emoji:'🌋',tag:'VOLCANIC ISLAND · KOREA',palette:['#f4ce91','#6b997c','#498797','#a65e48'],clues:['Hallasan, South Korea’s highest mountain, rises at the island’s center.','Jeju language has its own history and is distinct from standard Korean.','The haenyeo are celebrated women divers with a long local tradition.'],fact:'Jeju has a distinctive island history, but its residents are not defined by one custom or one way of speaking.',contrast:'Compare: Jeju’s island geography and local language history differ from mainland regions, while Korean is widely used across both.'},
+      {name:'Andalusia, Spain',short:'Andalusia',emoji:'🌼',tag:'SOUTHERN SPAIN · EUROPE',palette:['#efd089','#7a9c7d','#cb7655','#73a3a0'],clues:['Spanish is spoken with varied local accents across this region.','Flamenco developed here through Romani heritage and many cultural influences.','Granada’s Alhambra is one of the region’s historic landmarks.'],fact:'Andalusia is a large, diverse region. Flamenco is an important art form, not a trait shared by every resident.',contrast:'Compare: Catalonia has Catalan as a co-official language alongside Spanish; Andalusia’s official language is Spanish.'},
+      {name:'Zanzibar, Tanzania',short:'Zanzibar',emoji:'⛵',tag:'INDIAN OCEAN ISLANDS · TANZANIA',palette:['#f2d293','#398b81','#d27f5c','#65a5a0'],clues:['Kiswahili (Swahili) is widely spoken across the islands.','Stone Town reflects centuries of Indian Ocean exchange and layered histories.','Cloves and other spices have shaped parts of the islands’ trade and farming.'],fact:'Zanzibar’s culture reflects many histories and communities. No single food, language, or faith represents everyone.',contrast:'Compare: Zanzibar is an Indian Ocean archipelago with a distinct island history; mainland Tanzania is vast and regionally varied.'},
+      {name:'Québec, Canada',short:'Québec',emoji:'🍁',tag:'ST. LAWRENCE · CANADA',palette:['#f1cb87','#648c79','#6486a0','#d68560'],clues:['French is the province’s official language; English and Indigenous languages are also part of its story.','The St. Lawrence River runs past Québec City and Montréal.','Maple products are part of the region’s food culture, especially in spring.'],fact:'Québec is home to Indigenous nations and people with many origins. Language and identity are personal and varied.',contrast:'Compare: French is Québec’s official provincial language; Canada’s other provinces and territories have different language contexts.'}
+    ];
+    const lessons = [
+      {icon:'🗺️',title:'A map beats a guess',text:'Regions are places with histories, languages and changing borders—not boxes that neatly sort people. Look for context instead of trying to read identity from someone’s appearance.',contrast:'Try this: compare the geography, place names and languages mentioned in a clue. Those details point to a place; they never tell you everything about a person.'},
+      {icon:'🗣️',title:'One country, many languages',text:'National borders rarely match language borders. People may speak a local, Indigenous, national or family language—and switch between several in daily life.',contrast:'Oaxaca has many Indigenous languages alongside Spanish. In Québec, French is official, while English and Indigenous languages are also part of the province’s story.'},
+      {icon:'🌊',title:'Nearby places can differ',text:'Coasts, mountains, trade routes and migration all shape local histories. Neighboring regions can share a lot and still have distinct languages and traditions.',contrast:'Jeju’s island geography shaped a distinctive local history. Compare it with mainland Korea using place and language clues, not assumptions about people.'},
+      {icon:'🍲',title:'Traditions are not stereotypes',text:'Food, festivals, music and clothing are meaningful—but no tradition belongs to every person in a region. Communities change, overlap and create new traditions.',contrast:'Flamenco has deep roots in Andalusia and Romani culture, with many influences. It is an art form—not a shortcut for identifying anyone.'}
+    ];
+    const main = document.querySelector('#main');
+    let mode = 'play', round = [], turn = 0, score = 0, answered = false, picked = '';
+    let best = Number(localStorage.getItem('atlasBest') || 0);
+    let played = Number(localStorage.getItem('atlasPlayed') || 0);
+    const shuffle = arr => [...arr].sort(() => Math.random() - .5);
+    const startGame = () => { round = shuffle(places).slice(0,5); turn = 0; score = 0; answered = false; picked = ''; mode='play'; updateTabs(); renderGame(); };
+    const updateTabs = () => { document.querySelector('#playTab').classList.toggle('active',mode==='play');document.querySelector('#learnTab').classList.toggle('active',mode==='learn'); };
+    function landscape(place){
+      const [sky,green,accent,water]=place.palette;
+      return `<svg viewBox="0 0 760 310" role="img" aria-label="Illustrated landscape inspired by ${place.short}" preserveAspectRatio="xMidYMid slice"><defs><linearGradient id="sky" x2="0" y2="1"><stop stop-color="${sky}"/><stop offset="1" stop-color="#f9e3b2"/></linearGradient></defs><rect width="760" height="310" fill="url(#sky)"/><circle cx="610" cy="69" r="34" fill="#fff1cb" opacity=".8"/><path d="M0 191 113 105l91 77 103-110 126 116 93-89 126 94 108-104v221H0Z" fill="${green}" opacity=".78"/><path d="m0 230 130-83 111 97 91-75 114 92 126-102 103 78 85-57v130H0Z" fill="${accent}"/><path d="M0 246q100-25 186 5t166 0 165 0 243 0v59H0Z" fill="${water}"/><path d="M0 276q102-18 205 0t209 0 214 0 132 0v34H0Z" fill="#f5ebcf" opacity=".7"/>
+      <g fill="#f6ecd4" opacity=".88"><path d="M90 204v-32h33v32h10v-42h37v42h13v-24h29v24h15v-53h9v53h17v-34h32v34H90Z"/><path d="M430 202v-38h26v38h9v-53h37v53h12v-28h29v28h13v-45h43v45h14v-25h35v25h14v-42h31v42h12v-32h33v32Z"/></g><g fill="#f6ecd4"><path d="M146 154h8v13h-8zm65-15h8v11h-8zm249 0h8v10h-8zm111 5h8v12h-8z"/></g><path d="M522 213q8-46 17-64m-15 35-18-17m21 6 19-16m-27 21 18 2" stroke="#345c48" stroke-width="6" stroke-linecap="round" fill="none"/><path d="M20 229q16-49 32 0m-22-17-12-10m23 8 11-11" stroke="#345c48" stroke-width="5" fill="none" stroke-linecap="round"/><path d="M344 252q48-12 98 0" stroke="#fff4da" stroke-width="3" opacity=".6" fill="none"/></svg>`;
+    }

input.newString:
    }
    function renderGame(){
      updateTabs();
      const p=round[turn];
      if(!p){
        if(score>best){best=score;localStorage.setItem('atlasBest',best)}
        played++;localStorage.setItem('atlasPlayed',played);
        main.innerHTML=`<section class="question-card empty-state"><div class="result-icon">${score>=4?'🌟':score>=2?'🧭':'🌱'}</div><div class="eyebrow">JOURNEY COMPLETE</div><h2>${score>=4?'Beautifully explored!':score>=2?'Curiosity takes you far.':'Every journey starts somewhere.'}</h2><p>You got <strong>${score} out of 5</strong>. The best discoveries come from staying curious about places—and the people who make them home.</p><button class="primary" id="again">Explore another round&nbsp; ↗</button></section>`;
        document.querySelector('#again').onclick=startGame;return;
      }
      const options=shuffle([p,...shuffle(places.filter(x=>x!==p)).slice(0,3)]);
      main.innerHTML=`<div class="heading-row"><div><div class="eyebrow">A CULTURAL GEOGRAPHY GAME</div><h1>Where might this be?</h1><p>Follow the place clues. Every region holds more than one story.</p></div><div class="streak"><span class="streak-icon">✨</span><div><strong>${score} / ${turn}</strong><small>places explored</small></div></div></div>
        <div class="game-layout"><section class="question-card" aria-label="Quiz question"><div class="scene">${landscape(p)}<span class="scene-label">${p.tag}</span><span class="scene-sun" aria-hidden="true">${p.emoji}</span></div><div class="question-body"><div class="progress-row"><span class="progress-label">POSTCARD ${turn+1} OF 5</span><div class="progress-track" role="progressbar" aria-label="Round progress" aria-valuenow="${turn+1}" aria-valuemin="1" aria-valuemax="5"><div class="progress-fill" style="width:${(turn+1)*20}%"></div></div><span class="progress-label">${score} ✦</span></div><h2 class="question-title">Which place is this postcard about?</h2><p class="question-copy">Use the landscape and clues to choose a region—not a person.</p><div class="clue-list">${p.clues.map((c,i)=>`<span class="clue"><b>${['✳','⌁','◈'][i]}</b>${c}</span>`).join('')}</div><p class="answer-label">CHOOSE A PLACE</p><div class="answers">${options.map(o=>`<button class="answer-btn ${answered&&o===p?'correct':''} ${answered&&o.short===picked&&o!==p?'wrong':''}" type="button" data-answer="${o.short}" ${answered?'disabled':''}>${o.name}<span aria-hidden="true">${answered&&o===p?'✓':''}</span></button>`).join('')}</div>${answered?`<div class="feedback ${picked===p.short?'':'wrong-feedback'}" role="status"><strong>${picked===p.short?'That’s it!':'Not quite—now you know.'} ${p.name}</strong>${p.fact}<br><span style="display:block;margin-top:6px"><b>Regional note:</b> ${p.contrast}</span><button type="button" id="next">${turn===4?'See my results':'Next postcard'} &nbsp;→</button></div>`:''}</div></section>
        <aside class="aside-stack"><section class="side-card"><h2 class="side-title">A little field guide</h2>${lessons.slice(0,3).map((l,i)=>`<button type="button" class="lesson-link" data-lesson="${i}"><span class="lesson-icon">${l.icon}</span><span><strong>${l.title}</strong><small>${['Context over assumptions','Languages cross borders','Place shapes history'][i]}</small></span><span class="chevron">↗</span></button>`).join('')}<div class="side-stat"><span>Best round</span><strong>${best} / 5</strong></div><div class="side-stat"><span>Rounds played</span><strong>${played}</strong></div></section><div class="note-card"><div class="note-top"><span>✿</span> Curiosity, with care</div><p>People’s appearance can’t tell you their ethnicity or where they’re from. Here, we explore places through geography, language and history instead.</p></div></aside></div>`;
      main.querySelectorAll('[data-answer]').forEach(btn=>btn.addEventListener('click',()=>{picked=btn.dataset.answer;answered=true;if(picked===p.short)score++;renderGame()}));
      main.querySelector('#next')?.addEventListener('click',()=>{turn++;answered=false;picked='';renderGame()});
      main.querySelectorAll('[data-lesson]').forEach(btn=>btn.addEventListener('click',()=>renderLearn(Number(btn.dataset.lesson))));
    }
    function renderLearn(focus=0){
      mode='learn';updateTabs();
      main.innerHTML=`<section class="learn-head"><div class="eyebrow">THE FIELD GUIDE</div><h1>Learn to read a place.</h1><p>Clues like language, landscape and history help us understand regions. They never define everyone who lives there—and appearance is never a reliable guide to identity.</p></section><section class="lesson-grid">${lessons.map((l,i)=>`<article class="lesson-card" ${i===focus?'id="focus-lesson"':''}><div class="lesson-icon">${l.icon}</div><h2>${l.title}</h2><p>${l.text}</p><div class="contrast"><strong>Nearby, but not the same:</strong> ${l.contrast}</div></article>`).join('')}</section><div class="learn-foot"><strong>A note on labels:</strong> Ethnicity, nationality, language and regional identity are not interchangeable. People describe their own identities in their own ways. This game focuses on cultural geography—not guessing who someone is.</div><div style="margin-top:22px"><button type="button" class="primary" id="startExplore">Back to the postcards &nbsp;↗</button></div>`;
      document.querySelector('#startExplore').onclick=()=>{mode='play';updateTabs();round.length?renderGame():startGame()};
      if(focus) document.querySelector('#focus-lesson')?.scrollIntoView({behavior:'smooth',block:'center'});
    }
    document.querySelector('#playTab').addEventListener('click',()=>{if(mode==='play'&&round.length){renderGame()}else startGame()});
    document.querySelector('#learnTab').addEventListener('click',()=>renderLearn());
    startGame();
  </script>
</body>
</html>

