content.text:
    :root{--ink:#172b27;--muted:#75817a;--paper:#f6f3eb;--white:#fffefa;--green:#1d5749;--mint:#e7efe6;--orange:#df7048;--line:#e7e5dc;--serif:Georgia,'Times New Roman',serif;--sans:'DM Sans',Arial,sans-serif;--display:Manrope,'DM Sans',sans-serif;--shadow:0 12px 40px #193c2910}
    *{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:15px/1.5 var(--sans);min-height:100vh}button{font:inherit;color:inherit;cursor:pointer}a{color:inherit}.app{max-width:1160px;margin:auto;padding:0 38px}.topbar{height:80px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid #e8e4da}.brand{display:flex;align-items:center;gap:11px;text-decoration:none}.brand-mark{height:37px;width:37px;border-radius:12px;background:var(--green);display:grid;place-items:center;color:#fff;font-size:19px}.brand-name{font:800 17px var(--display);letter-spacing:-.7px}.brand-name span{color:var(--orange)}.nav{display:flex;align-items:center;gap:7px}.nav button{background:transparent;border:0;border-radius:9px;color:#68756f;padding:10px 15px;font-size:13px;font-weight:600}.nav button.active{background:#e8ebe2;color:var(--green)}.profile{border-left:1px solid var(--line);padding-left:21px;margin-left:12px;display:flex;align-items:center;gap:9px;color:#626f68;font-size:12px}.avatar{background:#e2c6a9;border-radius:50%;height:31px;width:31px;display:grid;place-items:center;font-size:16px}
    main{padding:42px 0 70px}.eyebrow{font-size:11px;letter-spacing:1.55px;text-transform:uppercase;font-weight:700;color:var(--green)}.heading-row{display:flex;align-items:flex-end;justify-content:space-between;gap:20px;margin-bottom:26px}.heading-row h1{font:700 33px/1.17 var(--display);letter-spacing:-1.5px;margin:9px 0 5px}.heading-row p{margin:0;color:var(--muted);font-size:14px}.streak{background:var(--white);border:1px solid var(--line);padding:11px 15px;border-radius:12px;display:flex;align-items:center;gap:10px;box-shadow:0 3px 12px #24372d08}.streak-icon{font-size:19px}.streak small{display:block;color:var(--muted);font-size:10px}.streak strong{font:700 14px var(--display)}
