62:         main.innerHTML=`<section class="question-card empty-state"><div class="result-icon">${score>=4?'🌟':score>=2?'🧭':'🌱'}</div><div class="eyebrow">JOURNEY COMPLETE</div><h2>${score>=4?'Beautifully explored!':score>=2?'Curiosity takes you far.':'Every journey starts somewhere.'}</h2><p>You got <strong>${score} out of 5</strong>. The best discoveries come from staying curious about places—and the people who make them home.</p><button class="primary" id="again">Explore another round&nbsp; ↗</button></section>`;
